import { ref } from 'vue';
import axios from 'axios';
import { ElMessage } from 'element-plus';
export default {
  __name: 'ContainerDetailDialog',
  setup(__props, {
    expose: __expose
  }) {
    const dialogVisible = ref(false);
    const container = ref(null);
    const containerIpMap = ref({});
    async function openDialog(containerData) {
      container.value = containerData;
      containerIpMap.value = {}; // 清空旧数据
      dialogVisible.value = true;
      try {
        const name = containerData.name.replace(/^\//, '');
        const response = await axios.get(`http://localhost:8081/container/ip/${name}`);
        containerIpMap.value = response.data;
      } catch (err) {
        ElMessage.error(`获取容器 IP 失败：${err?.response?.data || err.message}`);
      }
    }
    __expose({
      openDialog
    });
    const __returned__ = {
      dialogVisible,
      container,
      containerIpMap,
      openDialog,
      ref,
      get axios() {
        return axios;
      },
      get ElMessage() {
        return ElMessage;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
